import type { Vec3 } from '../contracts/math';
import type { GolfBallPhysics } from '../physics/GolfBallPhysics';
import { normalizeHorizontal } from '../physics/helpers';
import type { BoxTriggerConfig } from './types';

export function isBallInsideBox(ball: GolfBallPhysics, config: BoxTriggerConfig): boolean {
  const p = ball.position;
  return Math.abs(p.x - config.position.x) <= config.halfExtents.x
    && Math.abs(p.y - config.position.y) <= config.halfExtents.y
    && Math.abs(p.z - config.position.z) <= config.halfExtents.z;
}

export function enterOnce(activeBodies: Set<number>, ball: GolfBallPhysics, inside: boolean): boolean {
  const handle = ball.body.handle;
  if (!inside) {
    activeBodies.delete(handle);
    return false;
  }
  if (activeBodies.has(handle)) return false;
  activeBodies.add(handle);
  return true;
}

export function horizontalDirection(direction: Vec3): Vec3 {
  return normalizeHorizontal(direction) ?? { x: 0, y: 0, z: 1 };
}
