import RAPIER from '@dimforge/rapier3d-compat';
import type { GolfBallPhysics } from '../physics/GolfBallPhysics';
import { CollisionLayers, collisionGroups } from '../physics/CollisionLayers';
import type { PhysicsWorld } from '../physics/PhysicsWorld';
import type { SpringPadConfig } from './types';
import { enterOnce, isBallInsideBox } from './utils';

export class SpringPad {
  readonly collider: RAPIER.Collider;
  private readonly activeBodies = new Set<number>();

  constructor(physics: PhysicsWorld, readonly config: SpringPadConfig) {
    this.collider = physics.world.createCollider(
      RAPIER.ColliderDesc.cuboid(config.halfExtents.x, config.halfExtents.y, config.halfExtents.z)
        .setTranslation(config.position.x, config.position.y, config.position.z)
        .setSensor(true)
        .setCollisionGroups(collisionGroups(CollisionLayers.SENSOR, CollisionLayers.BALL)),
    );
  }

  update(ball: GolfBallPhysics): boolean {
    if (!enterOnce(this.activeBodies, ball, isBallInsideBox(ball, this.config))) return false;
    ball.body.wakeUp();
    ball.body.applyImpulse({ x: 0, y: this.config.impulse, z: 0 }, true);
    return true;
  }
}
