import RAPIER from '@dimforge/rapier3d-compat';
import type { GolfBallPhysics } from '../physics/GolfBallPhysics';
import { CollisionLayers, collisionGroups } from '../physics/CollisionLayers';
import type { PhysicsWorld } from '../physics/PhysicsWorld';
import type { BumperConfig } from './types';
import { enterOnce } from './utils';

export class Bumper {
  readonly collider: RAPIER.Collider;
  readonly trigger: RAPIER.Collider;
  private readonly activeBodies = new Set<number>();

  constructor(physics: PhysicsWorld, readonly config: BumperConfig) {
    const obstacleGroups = collisionGroups(CollisionLayers.OBSTACLE, CollisionLayers.BALL);
    const sensorGroups = collisionGroups(CollisionLayers.SENSOR, CollisionLayers.BALL);
    this.collider = physics.world.createCollider(
      RAPIER.ColliderDesc.cylinder(config.halfHeight, config.radius)
        .setTranslation(config.position.x, config.position.y, config.position.z)
        .setRestitution(config.restitution ?? 0.9)
        .setCollisionGroups(obstacleGroups),
    );
    this.trigger = physics.world.createCollider(
      RAPIER.ColliderDesc.cylinder(config.halfHeight, config.radius + (config.triggerPadding ?? 0.3))
        .setTranslation(config.position.x, config.position.y, config.position.z)
        .setSensor(true)
        .setCollisionGroups(sensorGroups),
    );
  }

  update(ball: GolfBallPhysics): boolean {
    const p = ball.position;
    const dx = p.x - this.config.position.x;
    const dz = p.z - this.config.position.z;
    const radius = this.config.radius + (this.config.triggerPadding ?? 0.3);
    const inside = Math.hypot(dx, dz) <= radius
      && Math.abs(p.y - this.config.position.y) <= this.config.halfHeight + 0.5;
    if (!enterOnce(this.activeBodies, ball, inside)) return false;

    const length = Math.hypot(dx, dz);
    const x = length > 1e-8 ? dx / length : 1;
    const z = length > 1e-8 ? dz / length : 0;
    ball.body.wakeUp();
    ball.body.applyImpulse({ x: x * this.config.impulse, y: 0, z: z * this.config.impulse }, true);
    return true;
  }
}
