import RAPIER from '@dimforge/rapier3d-compat';
import { beforeAll, describe, expect, it } from 'vitest';
import { GolfBallPhysics } from '../physics/GolfBallPhysics';
import { PhysicsWorld } from '../physics/PhysicsWorld';
import { Bumper } from './Bumper';
import { BoostPad } from './BoostPad';
import { JumpPad } from './JumpPad';
import { SpringPad } from './SpringPad';

beforeAll(async () => {
  await RAPIER.init();
});

function makeWorldAndBall(position = { x: 0, y: 0, z: 0 }) {
  const physics = new PhysicsWorld({ x: 0, y: 0, z: 0 });
  const ball = new GolfBallPhysics(physics, position, { rollingResistance: 0, airResistance: 0 });
  return { physics, ball };
}

describe('pads and bumper', () => {
  it('SpringPad applies an upward impulse only once until the ball leaves and re-enters', () => {
    const { physics, ball } = makeWorldAndBall();
    const pad = new SpringPad(physics, {
      position: { x: 0, y: 0, z: 0 },
      halfExtents: { x: 1, y: 0.5, z: 1 },
      impulse: 2,
    });

    expect(pad.update(ball)).toBe(true);
    const first = ball.velocity.y;
    expect(first).toBeGreaterThan(0);
    expect(pad.update(ball)).toBe(false);
    expect(ball.velocity.y).toBeCloseTo(first);

    ball.body.setTranslation({ x: 3, y: 0, z: 0 }, true);
    expect(pad.update(ball)).toBe(false);
    ball.body.setTranslation({ x: 0, y: 0, z: 0 }, true);
    expect(pad.update(ball)).toBe(true);
    expect(ball.velocity.y).toBeGreaterThan(first);
    physics.dispose();
  });

  it('BoostPad normalizes its configured direction and adds horizontal impulse', () => {
    const { physics, ball } = makeWorldAndBall();
    const pad = new BoostPad(physics, {
      position: { x: 0, y: 0, z: 0 },
      halfExtents: { x: 1, y: 0.5, z: 1 },
      direction: { x: 10, y: 5, z: 0 },
      impulse: 3,
    });

    expect(pad.update(ball)).toBe(true);
    expect(ball.velocity.x).toBeGreaterThan(0);
    expect(ball.velocity.y).toBeCloseTo(0);
    expect(ball.velocity.z).toBeCloseTo(0);
    physics.dispose();
  });

  it('JumpPad combines forward and vertical impulses', () => {
    const { physics, ball } = makeWorldAndBall();
    const pad = new JumpPad(physics, {
      position: { x: 0, y: 0, z: 0 },
      halfExtents: { x: 1, y: 0.5, z: 1 },
      direction: { x: 0, y: 0, z: 1 },
      forwardImpulse: 1.5,
      verticalImpulse: 2.5,
    });

    expect(pad.update(ball)).toBe(true);
    expect(ball.velocity.z).toBeGreaterThan(0);
    expect(ball.velocity.y).toBeGreaterThan(0);
    physics.dispose();
  });

  it('Bumper creates a solid collider and pushes the ball away from its center once per contact', () => {
    const { physics, ball } = makeWorldAndBall({ x: 1, y: 0, z: 0 });
    const bumper = new Bumper(physics, {
      position: { x: 0, y: 0, z: 0 },
      radius: 0.8,
      halfHeight: 0.5,
      impulse: 2,
      triggerPadding: 0.4,
    });

    expect(bumper.collider.isSensor()).toBe(false);
    expect(bumper.trigger.isSensor()).toBe(true);
    expect(bumper.update(ball)).toBe(true);
    expect(ball.velocity.x).toBeGreaterThan(0);
    const first = ball.velocity.x;
    expect(bumper.update(ball)).toBe(false);
    expect(ball.velocity.x).toBeCloseTo(first);
    physics.dispose();
  });
});
